ConstValues.value:
"{
  "version": 1,
  "sessionTimeoutMinutes": 30,
  "activeDaysRetain": 90,
  "limitErrorCodes": [402, 429, 403],
  "quotaBump": {
    "soft_monthly": "monthly_pro",
    "starter": "monthly_pro",
    "discount": "monthly_pro",
    "monthly_pro": "annual_pro",
    "photo_pack": "annual_pro",
    "video_pack": "annual_pro",
    "agent_pack": "annual_pro",
    "food_pack": "annual_pro",
    "winback": "discount",
    "winback_soft": "discount"
  },
  "featurePathMap": {
    "app/api-pro/image-editing/process": "photo",
    "app/api-pro/ai-tool/user-image/edit-option": "photo",
    "app/v2/ai-tool/user-image/edit-option": "photo",
    "app/api-pro/agent/general/process": "agent",
    "app/v2/assistance/characters/create": "agent",
    "app/v2/assistance/characters/update": "agent",
    "app/v2/assistance/characters/delete": "agent",
    "app/ai/api/v1/chat/send": "agent",
    "app/v2/calorie/search-food": "food",
    "app/v2/calorie/detail-food": "food"
  },
  "rules": [
    {
      "id": "newUser",
      "enabled": true,
      "offerCode": "none",
      "when": {
        "all": [
          { "metric": "daysSinceInstall", "op": "lt", "value": 2 },
          { "metric": "sessionCount", "op": "lte", "value": 3 }
        ]
      }
    },
    {
      "id": "churned",
      "enabled": true,
      "offerCode": "winback",
      "when": {
        "all": [
          { "metric": "daysSinceLastOpen", "op": "gte", "value": 30 }
        ]
      }
    },
    {
      "id": "dormant",
      "enabled": true,
      "offerCode": "winback_soft",
      "when": {
        "all": [
          { "metric": "daysSinceLastOpen", "op": "gte", "value": 14 }
        ]
      }
    },
    {
      "id": "quotaBlocked",
      "enabled": true,
      "offerCode": "annual_pro",
      "when": {
        "all": [
          { "metric": "quotaOrLimitHits", "op": "gte", "value": 1 },
          { "metric": "sessionsLast7d", "op": "gte", "value": 2 }
        ]
      }
    },
    {
      "id": "atRisk",
      "enabled": true,
      "offerCode": "discount",
      "when": {
        "all": [
          { "metric": "sessionsLast30d", "op": "gte", "value": 5 },
          { "metric": "sessionsLast7d", "op": "lte", "value": 1 },
          { "metric": "daysSinceLastOpen", "op": "gte", "value": 3 }
        ]
      }
    },
    {
      "id": "powerUser",
      "enabled": true,
      "offerCode": "annual_pro",
      "when": {
        "all": [
          { "metric": "sessionsLast7d", "op": "gte", "value": 5 },
          { "metric": "totalFeatureCountLast7d", "op": "gte", "value": 10 },
          { "metric": "retainedD7", "op": "eq", "value": 1 }
        ]
      }
    },
    {
      "id": "photoHeavy",
      "enabled": true,
      "offerCode": "photo_pack",
      "when": {
        "all": [
          { "metric": "totalFeatureCount", "op": "gte", "value": 5 },
          { "metric": "photoShare", "op": "gte", "value": 0.7 }
        ]
      }
    },
    {
      "id": "videoHeavy",
      "enabled": true,
      "offerCode": "video_pack",
      "when": {
        "all": [
          { "metric": "totalFeatureCount", "op": "gte", "value": 5 },
          { "metric": "videoShare", "op": "gte", "value": 0.7 }
        ]
      }
    },
    {
      "id": "agentHeavy",
      "enabled": true,
      "offerCode": "agent_pack",
      "when": {
        "all": [
          { "metric": "totalFeatureCount", "op": "gte", "value": 5 },
          { "metric": "agentShare", "op": "gte", "value": 0.7 }
        ]
      }
    },
    {
      "id": "foodHeavy",
      "enabled": true,
      "offerCode": "food_pack",
      "when": {
        "all": [
          { "metric": "totalFeatureCount", "op": "gte", "value": 5 },
          { "metric": "foodShare", "op": "gte", "value": 0.7 }
        ]
      }
    },
    {
      "id": "engagedFree",
      "enabled": true,
      "offerCode": "monthly_pro",
      "when": {
        "all": [
          { "metric": "daysSinceInstall", "op": "gte", "value": 7 },
          { "any": [
            { "metric": "sessionsLast7d", "op": "gte", "value": 4 },
            { "metric": "activeDaysLast7d", "op": "gte", "value": 4 }
          ]}
        ]
      }
    },
    {
      "id": "explorer",
      "enabled": true,
      "offerCode": "starter",
      "when": {
        "all": [
          { "metric": "daysSinceInstall", "op": "gte", "value": 2 },
          { "metric": "daysSinceInstall", "op": "lt", "value": 7 },
          { "metric": "uniqueFeatureCount", "op": "gte", "value": 2 }
        ]
      }
    },
    {
      "id": "casual",
      "enabled": true,
      "fallback": true,
      "offerCode": "soft_monthly",
      "when": { "all": [] }
    }
  ]
}"
